// One topic per pooja offered on the site — rotates daily (see topic-calendar.csv for the full 52-day list).
const calendar = [
  { "topic": "Mangal Dosh Puja significance and benefits", "keyword": "mangal dosh puja benefits", "cta": "Mangal Dosh Puja" },
  { "topic": "Kaal Sarp Dosh Puja cost in Ujjain", "keyword": "kaal sarp dosh puja cost ujjain", "cta": "Kaal Sarp Dosh Puja" },
  { "topic": "Rudrabhishek benefits for devotees", "keyword": "rudrabhishek benefits", "cta": "Rudrabhishek" },
  { "topic": "Mahamrityunjay Jaap benefits for health and peace", "keyword": "mahamrityunjay jaap benefits", "cta": "Mahamrityunjay Jaap" },
  { "topic": "Navgrah Shanti Puja significance and benefits", "keyword": "navgrah shanti puja benefits", "cta": "Navgrah Shanti Puja" },
  { "topic": "Pitra Dosh Shanti remedies and shanti pooja details", "keyword": "pitra dosh shanti benefits", "cta": "Pitru Dosh Shanti" },
  { "topic": "Ark Vivah what it is and its importance", "keyword": "ark vivah significance", "cta": "Ark Vivah" },
  { "topic": "Kumbh Vivah what it is and its importance", "keyword": "kumbh vivah significance", "cta": "Kumbh Vivah" },
  { "topic": "Narayan Bali significance and when to perform", "keyword": "narayan bali significance", "cta": "Narayan Bali" },
  { "topic": "Nag Bali significance and benefits", "keyword": "nag bali pooja benefits", "cta": "Nag Bali" },
  { "topic": "Vastu Puja significance and benefits", "keyword": "vastu puja benefits", "cta": "Vastu Puja" },
  { "topic": "Durga Saptashati Path significance and benefits", "keyword": "durga saptashati path benefits", "cta": "Durga Saptashati Path" }
];
const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
const pick = calendar[dayOfYear % calendar.length];
return [{ json: {
  topic: pick.topic,
  keyword: pick.keyword,
  cta: pick.cta,
  date: new Date().toISOString().slice(0, 10),
  slugBase: pick.topic.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')
} }];

// Assemble markdown (with priest author box) + Article JSON-LD from the AI response.
const ai = typeof $json.content === 'string' ? JSON.parse($json.content) : $json;
const siteUrl = 'https://www.panditabhishekvyas.in';
const slug = $('Pick Today's Topic (12 poojas)').item.json.slugBase + '-' + $('Pick Today's Topic (12 poojas)').item.json.date;
const date = $('Pick Today's Topic (12 poojas)').item.json.date;
const faqBlock = ai.faq.map(f => `### ${f.q}

${f.a}`).join('

');
const cta = `---

## Book Your Pooja

Book ${ai.title} at Mangalnath / Mahakal Temple, Ujjain with Pt. Abhishek Vyas — 100% private puja, no agents. [Book on WhatsApp](https://wa.me/916260552014?text=${encodeURIComponent('Namaste! I want to book: ' + ai.title)}) or see all [pooja services](https://www.panditabhishekvyas.in/#poojas).`;
const priest = `---

## About Your Acharya — Pt. Abhishek Vyas

Every pooja is performed personally by **Pt. Abhishek Vyas** (Acharya), an experienced Vedic Pandit at **Mangalnath Temple & Mahakal Temple, Ujjain**. 100% private puja, direct pandit booking, no agents — with a pooja certificate and photos/videos shared after the ritual.

- 📞 Call / WhatsApp: **+91 6260552014**
- 📧 Email: abhishekvyas069@gmail.com
- 🙏 Book online: [All Pooja Services](https://www.panditabhishekvyas.in/#poojas)`;
const frontmatter = `---
title: "${ai.title}"
description: "${ai.description}"
date: "${date}"
keywords: [${ai.keywords.map(k => `"${k}"`).join(', ')}]
ctaPooja: "${$('Pick Today's Topic (12 poojas)').item.json.cta}"
---

`;
const markdown = frontmatter + ai.body + '

' + faqBlock + '

' + cta + '

' + priest + '
';
const articleJsonLd = {
  '@context': 'https://schema.org',
  '@type': 'Article',
  headline: ai.title,
  description: ai.description,
  datePublished: date,
  author: { '@type': 'Person', name: 'Pt. Abhishek Vyas' },
  publisher: { '@type': 'Organization', name: 'Mahakal Pooja Services', url: siteUrl }
};
return [{ json: {
  markdown,
  articleJsonLd: JSON.stringify(articleJsonLd),
  slug,
  title: ai.title,
  description: ai.description,
  url: `${siteUrl}/blog/${slug}`
} }];
